from PIL import Image
import numpy as np
from collections import deque
im=np.asarray(Image.open('/app/output/initial/last/topview.jpg'))
m=(im[:,:,1]>120)&(im[:,:,1]>im[:,:,0]*1.3)&(im[:,:,1]>im[:,:,2]*1.2)
H,W=m.shape; seen=np.zeros_like(m); comps=[]
for y in range(H):
 for x in np.flatnonzero(m[y]):
  if seen[y,x]: continue
  q=[(y,int(x))];seen[y,x]=1; pix=[]
  while q:
   yy,xx=q.pop();pix.append((yy,xx))
   for Y,X in [(yy-1,xx),(yy+1,xx),(yy,xx-1),(yy,xx+1)]:
    if 0<=Y<H and 0<=X<W and m[Y,X] and not seen[Y,X]:seen[Y,X]=1;q.append((Y,X))
  if len(pix)>3:
   a=np.array(pix);comps.append((len(pix),a[:,1].min(),a[:,1].max(),a[:,0].min(),a[:,0].max(),a[:,1].mean(),a[:,0].mean()))
print(sorted(comps,reverse=True)[:20])
